// Stub: @anthropic-ai/sandbox-runtime is not included in this fork.
// All sandbox features are disabled — methods return safe no-op defaults.

class SandboxManager {
  constructor() {}
  async initialize() {}
  async dispose() {}
  isActive() { return false; }

  // Static methods used by sandbox-adapter.ts
  static isSupportedPlatform() { return false; }
  static checkDependencies() { return { supported: false, missing: [] }; }
  static async wrapWithSandbox(cmd, args, opts) { return { command: cmd, args, ...opts }; }
  static updateConfig() {}
  static async reset() {}
  static getFsReadConfig() { return undefined; }
  static getFsWriteConfig() { return undefined; }
  static getNetworkRestrictionConfig() { return undefined; }
  static getIgnoreViolations() { return false; }
  static getAllowUnixSockets() { return true; }
  static getAllowLocalBinding() { return true; }
  static getEnableWeakerNestedSandbox() { return false; }
  static getProxyPort() { return undefined; }
  static getSocksProxyPort() { return undefined; }
  static getLinuxHttpSocketPath() { return undefined; }
  static getLinuxSocksSocketPath() { return undefined; }
  static async waitForNetworkInitialization() {}
  static getSandboxViolationStore() { return new SandboxViolationStore(); }
  static annotateStderrWithSandboxFailures(stderr) { return stderr; }
  static async cleanupAfterCommand() {}
}

class SandboxViolationStore {
  constructor() {}
  getViolations() { return []; }
  clear() {}
}

let SandboxRuntimeConfigSchema;
try {
  const { z } = require('zod');
  SandboxRuntimeConfigSchema = z.object({}).passthrough();
} catch {
  SandboxRuntimeConfigSchema = { parse: (v) => v, safeParse: (v) => ({ success: true, data: v }) };
}

module.exports = {
  SandboxManager,
  SandboxViolationStore,
  SandboxRuntimeConfigSchema,
};
